<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Proof of Digital Folklore</title>
<style>
:root{
  --ink:#15120e;
  --paper:#eee6d5;
  --cream:#f7f1e5;
  --rust:#a74324;
  --gold:#d49b3d;
  --line:rgba(37,27,16,.22)
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  color:var(--ink);
  background:
    radial-gradient(circle at 20% 0%,rgba(208,151,57,.13),transparent 28rem),
    repeating-linear-gradient(90deg,rgba(55,37,16,.025) 0 1px,transparent 1px 9px),
    var(--paper);
  font-family:Georgia,"Times New Roman",serif
}
button,a{font:inherit}
.site-head{
  position:absolute;
  z-index:4;
  inset:0 0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:22px clamp(20px,5vw,72px);
  color:#f4ead7
}
.wordmark{
  display:flex;
  align-items:center;
  gap:12px;
  font:700 14px/1 Arial,sans-serif;
  letter-spacing:.18em;
  text-transform:uppercase
}
.wordmark i{
  width:32px;height:32px;border:1px solid #c99043;border-radius:50%;
  display:grid;place-items:center;font-style:normal;color:#d9a452
}
.site-head a{color:inherit;text-decoration:none;font:700 11px Arial,sans-serif;letter-spacing:.17em;text-transform:uppercase}
.hero{
  min-height:760px;
  height:100vh;
  position:relative;
  display:grid;
  place-items:center;
  overflow:hidden;
  background:#17130f
}
#coin-hero{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  display:block
}
.hero-copy{
  position:absolute;
  z-index:2;
  left:clamp(22px,6vw,90px);
  bottom:clamp(35px,8vh,90px);
  color:#f5ecdc;
  pointer-events:none
}
.eyebrow{
  margin:0 0 12px;
  font:700 11px/1.4 Arial,sans-serif;
  letter-spacing:.28em;
  text-transform:uppercase;
  color:#d99c48
}
h1{
  margin:0;
  max-width:650px;
  font-size:clamp(46px,7vw,104px);
  line-height:.84;
  letter-spacing:-.055em;
  font-weight:400
}
.hero-copy .sub{
  margin:22px 0 0;
  max-width:410px;
  font-size:15px;
  line-height:1.55;
  color:#cabfae
}
.scroll{
  position:absolute;right:clamp(22px,5vw,70px);bottom:46px;z-index:2;
  color:#a99c89;font:10px Arial,sans-serif;letter-spacing:.22em;
  writing-mode:vertical-rl;text-transform:uppercase
}
main{overflow:hidden}
.about{
  max-width:1250px;
  margin:auto;
  padding:clamp(90px,13vw,180px) clamp(22px,6vw,82px);
  display:grid;
  grid-template-columns:.7fr 1.3fr;
  gap:clamp(40px,8vw,130px);
  border-bottom:1px solid var(--line)
}
.section-num{
  font:700 11px Arial,sans-serif;
  letter-spacing:.22em;
  text-transform:uppercase;
  color:var(--rust)
}
.about h2,.collection-head h2{
  font-size:clamp(43px,6vw,82px);
  line-height:.96;
  letter-spacing:-.045em;
  font-weight:400;
  margin:0
}
.about-copy p{
  margin:0 0 24px;
  font-size:clamp(19px,2vw,27px);
  line-height:1.42
}
.about-copy p:last-child{font-size:16px;color:#625a4e;max-width:690px}
.collection{max-width:1400px;margin:auto;padding:110px clamp(18px,4vw,60px) 150px}
.collection-head{
  display:flex;align-items:end;justify-content:space-between;gap:30px;
  margin-bottom:55px;padding:0 8px
}
.collection-head p{margin:0;max-width:350px;color:#6e6457;line-height:1.5}
.editions{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.edition{
  min-width:0;
  border:1px solid var(--line);
  background:rgba(249,244,233,.55);
  padding:14px 14px 20px;
  position:relative;
  transition:transform .35s,box-shadow .35s
}
.edition:hover{transform:translateY(-7px);box-shadow:0 18px 38px rgba(55,36,14,.13)}
.edition-canvas{display:block;width:100%;aspect-ratio:1;background:#dcd2c0}
.ed-meta{padding:22px 5px 5px}
.ed-top{display:flex;justify-content:space-between;gap:12px;align-items:start}
.edition h3{font-size:27px;font-weight:400;margin:0}
.serial{font:10px Arial,sans-serif;letter-spacing:.15em;color:#857867;margin-top:7px}
.state{
  display:inline-block;margin:12px 0 16px;
  font:700 10px Arial,sans-serif;letter-spacing:.15em;text-transform:uppercase;color:#557046
}
[data-state="sold-out"]{filter:saturate(.38)}
[data-state="sold-out"] .state{color:#a03725}
[data-state="coming-soon"] .state{color:#5d5265}
[data-state="sold-out"]::after{
  content:"ARCHIVED";position:absolute;top:27px;right:24px;
  border:1px solid rgba(255,255,255,.7);padding:7px 9px;
  color:#fff;font:700 9px Arial,sans-serif;letter-spacing:.16em;
  transform:rotate(5deg)
}
.buy{
  width:100%;border:1px solid #262017;background:transparent;color:#262017;
  padding:13px 15px;cursor:pointer;
  font:700 10px Arial,sans-serif;letter-spacing:.18em;text-transform:uppercase;
  transition:.2s
}
.buy:hover{background:#211b15;color:#f2e9d9}
.unavailable{
  border-top:1px solid var(--line);padding-top:13px;
  color:#7e7366;font:10px Arial,sans-serif;letter-spacing:.13em;text-transform:uppercase
}
footer{
  background:#18140f;color:#c8bcaa;
  padding:55px clamp(22px,6vw,82px);
  display:flex;justify-content:space-between;gap:30px;align-items:end
}
footer strong{display:block;color:#f2e6d2;font-size:25px;font-weight:400;margin-bottom:8px}
footer small{font:10px Arial,sans-serif;letter-spacing:.15em;text-transform:uppercase}
@media(max-width:1000px){.editions{grid-template-columns:repeat(2,1fr)}}
@media(max-width:680px){
  .hero{height:820px}.hero-copy{bottom:45px}.scroll{display:none}
  .about{grid-template-columns:1fr}.collection-head{display:block}.collection-head p{margin-top:20px}
  .editions{grid-template-columns:1fr}footer{display:block}footer small{display:block;margin-top:25px}
}
</style>
</head>
<body>
<header class="site-head">
  <div class="wordmark"><i>W</i> WastedToken Mint</div>
  <a href="#editions">View the drop ↓</a>
</header>

<section class="hero">
  <canvas id="coin-hero" aria-label="Rotating WastedToken challenge coin"></canvas>
  <div class="hero-copy">
    <p class="eyebrow">Physical proof of digital folklore</p>
    <h1>Spend nothing.<br>Keep everything.</h1>
    <p class="sub">Heavy-struck challenge coins for the builders, breakers, lurkers and legends who made the internet strange.</p>
  </div>
  <div class="scroll">Minted in small numbers</div>
</section>

<main>
  <section class="about">
    <div class="section-num">01 / The Mint</div>
    <div class="about-copy">
      <h2>Artifacts for time<br>well wasted.</h2>
      <p>WastedToken Mint turns fleeting online moments into objects with weight, patina and permanence.</p>
      <p>Every edition begins as an original sculpt, then receives a deep relief strike, hand-finished edge and individual mint number. No blockchain, no battery, no terms of service—just metal built to outlive the thread that inspired it.</p>
    </div>
  </section>

  <section class="collection" id="editions">
    <div class="collection-head">
      <div><p class="section-num">02 / Current ledger</p><h2>Choose your weight.</h2></div>
      <p>Four finishes. One stubborn little emblem. Each coin is 44 mm, satisfyingly overbuilt, and shipped in a numbered field case.</p>
    </div>

    <div class="editions">
      <div class="edition" data-edition="bronze" data-state="available">
        <canvas class="edition-canvas"></canvas>
        <div class="ed-meta">
          <div class="ed-top"><h3>Bronze</h3><span class="serial">WT–01</span></div>
          <div class="state">Available · 248 remain</div>
          <button class="buy">Add to cart</button>
        </div>
      </div>

      <div class="edition" data-edition="silver" data-state="available">
        <canvas class="edition-canvas"></canvas>
        <div class="ed-meta">
          <div class="ed-top"><h3>Silver</h3><span class="serial">WT–02</span></div>
          <div class="state">Available · 91 remain</div>
          <button class="buy">Add to cart</button>
        </div>
      </div>

      <div class="edition" data-edition="gold" data-state="sold-out">
        <canvas class="edition-canvas"></canvas>
        <div class="ed-meta">
          <div class="ed-top"><h3>Gold</h3><span class="serial">WT–03</span></div>
          <div class="state">SOLD OUT</div>
          <div class="unavailable">Edition permanently closed</div>
        </div>
      </div>

      <div class="edition" data-edition="black" data-state="coming-soon">
        <canvas class="edition-canvas"></canvas>
        <div class="ed-meta">
          <div class="ed-top"><h3>Obsidian</h3><span class="serial">WT–04</span></div>
          <div class="state">MINTING NEXT SEASON · AUTUMN</div>
          <div class="unavailable">Join the autumn mint ledger</div>
        </div>
      </div>
    </div>
  </section>
</main>

<footer>
  <div><strong>WastedToken Mint</strong><small>Objects for the terminally online</small></div>
  <small>Est. 2026 · Somewhere between tabs</small>
</footer>

<script>
(() => {
  const hero = document.getElementById("coin-hero");
  const hc = hero.getContext("2d");
  let running = true, raf = 0, start = performance.now();

  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));

  function faceTexture(side, palette, size=700){
    const c=document.createElement("canvas"),x=c.getContext("2d");
    c.width=c.height=size;
    const q=size/2,r=size*.485;

    let g=x.createRadialGradient(q*.67,q*.58,10,q,q,r);
    g.addColorStop(0,palette.light);
    g.addColorStop(.38,palette.mid);
    g.addColorStop(.78,palette.dark);
    g.addColorStop(1,palette.edge);
    x.fillStyle=g;x.beginPath();x.arc(q,q,r,0,Math.PI*2);x.fill();

    x.save();x.translate(q,q);
    x.strokeStyle=palette.shadow;x.lineWidth=22;
    x.beginPath();x.arc(0,0,r*.85,0,Math.PI*2);x.stroke();
    x.strokeStyle=palette.hi;x.lineWidth=7;
    x.beginPath();x.arc(0,0,r*.82,0,Math.PI*2);x.stroke();

    for(let i=0;i<72;i++){
      const a=i*Math.PI*2/72;
      x.strokeStyle=i%2?palette.shadow:palette.hi;
      x.lineWidth=3;
      x.beginPath();
      x.moveTo(Math.cos(a)*r*.89,Math.sin(a)*r*.89);
      x.lineTo(Math.cos(a)*r*.94,Math.sin(a)*r*.94);
      x.stroke()
    }

    x.textAlign="center";x.textBaseline="middle";
    if(side==="front"){
      reliefText(x,"WASTEDTOKEN",0,-r*.61,size*.052,palette);
      reliefText(x,"MINT • INTERNET ARTIFACT •",0,r*.62,size*.031,palette);

      x.save();x.rotate(-.12);
      reliefPath(x,palette,()=>{
        x.moveTo(-104,-78);x.lineTo(68,-78);x.quadraticCurveTo(116,-78,105,-30);
        x.lineTo(80,82);x.quadraticCurveTo(72,115,36,115);
        x.lineTo(-72,115);x.quadraticCurveTo(-102,112,-96,78);
        x.lineTo(-73,-27);x.quadraticCurveTo(-67,-56,-104,-78);
        x.closePath()
      });
      x.fillStyle=palette.shadow;
      for(let i=0;i<3;i++)x.fillRect(-38+i*43,-38,18,105);
      x.fillStyle=palette.hi;x.fillRect(-53,-61,130,15);
      x.restore();

      reliefText(x,"W",0,5,size*.23,palette,"900 Arial");
      x.font="700 27px Arial";x.letterSpacing="4px";
      x.fillStyle=palette.shadow;x.fillText("PROOF OF WASTE",0,r*.43);
      x.fillStyle=palette.hi;x.fillText("PROOF OF WASTE",0,r*.43-3);
    }else{
      reliefText(x,"TOKEN RESERVE",0,-r*.61,size*.052,palette);
      reliefText(x,"NON-TRANSFERABLE • ALWAYS YOURS",0,r*.62,size*.027,palette);
      reliefText(x,"10,000",0,-24,size*.19,palette,"900 Arial");
      reliefText(x,"TOKENS",0,76,size*.075,palette,"900 Arial");
      x.strokeStyle=palette.shadow;x.lineWidth=8;
      x.beginPath();x.moveTo(-150,116);x.lineTo(150,116);x.stroke();
      x.strokeStyle=palette.hi;x.lineWidth=3;
      x.beginPath();x.moveTo(-150,110);x.lineTo(150,110);x.stroke();
      x.font="700 24px Arial";x.fillStyle=palette.shadow;
      x.fillText("NO CASH VALUE",0,151);
      x.fillStyle=palette.hi;x.fillText("NO CASH VALUE",0,148);
      for(let i=0;i<8;i++){
        const a=i*Math.PI/4;
        reliefPath(x,palette,()=>{
          const px=Math.cos(a)*r*.45,py=Math.sin(a)*r*.45;
          x.arc(px,py,10,0,Math.PI*2)
        })
      }
    }
    x.restore();

    x.globalCompositeOperation="soft-light";
    const shine=x.createLinearGradient(0,size,size,0);
    shine.addColorStop(0,"rgba(255,255,255,.4)");
    shine.addColorStop(.35,"rgba(255,255,255,0)");
    shine.addColorStop(.67,"rgba(0,0,0,.3)");
    shine.addColorStop(1,"rgba(255,255,255,.25)");
    x.fillStyle=shine;x.beginPath();x.arc(q,q,r,0,Math.PI*2);x.fill();
    x.globalCompositeOperation="source-over";
    return c
  }

  function reliefText(x,text,px,py,size,p,font){
    x.font=font||`900 ${size}px Arial`;
    x.textAlign="center";x.textBaseline="middle";
    x.fillStyle=p.shadow;x.fillText(text,px+4,py+7);
    x.strokeStyle=p.shadow;x.lineWidth=Math.max(2,size*.06);x.strokeText(text,px,py);
    x.fillStyle=p.hi;x.fillText(text,px-2,py-3);
    x.fillStyle=p.mid;x.fillText(text,px,py)
  }

  function reliefPath(x,p,fn){
    x.beginPath();fn();x.fillStyle=p.shadow;x.save();x.translate(5,8);x.fill();x.restore();
    x.beginPath();fn();x.fillStyle=p.hi;x.fill();
    x.save();x.translate(0,3);x.beginPath();fn();x.fillStyle=p.mid;x.fill();x.restore()
  }

  const bronze={light:"#ffd28a",mid:"#b87132",dark:"#75401f",edge:"#301b10",shadow:"#5c2c16",hi:"#f3b95f"};
  const silver={light:"#ffffff",mid:"#aeb7bc",dark:"#626a70",edge:"#272c30",shadow:"#555d62",hi:"#eef5f5"};
  const gold={light:"#fff0a4",mid:"#d5a12e",dark:"#8c5917",edge:"#40290d",shadow:"#7b4a10",hi:"#ffe37b"};
  const black={light:"#697078",mid:"#24292e",dark:"#0c1014",edge:"#020304",shadow:"#050608",hi:"#8a979d"};
  const front=faceTexture("front",bronze), back=faceTexture("back",bronze);

  function fitHero(){
    const d=Math.min(devicePixelRatio||1,2);
    const r=hero.getBoundingClientRect();
    const w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));
    if(hero.width!==w||hero.height!==h){hero.width=w;hero.height=h}
  }

  function render(t){
    fitHero();
    const W=hero.width,H=hero.height,ctx=hc;
    t=((+t||0)%1+1)%1;
    ctx.setTransform(1,0,0,1,0,0);
    const bg=ctx.createRadialGradient(W*.59,H*.43,20,W*.54,H*.46,Math.max(W,H)*.75);
    bg.addColorStop(0,"#35281c");bg.addColorStop(.35,"#201a14");bg.addColorStop(1,"#0d0b09");
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

    const vign=ctx.createLinearGradient(0,0,W,0);
    vign.addColorStop(0,"rgba(0,0,0,.38)");vign.addColorStop(.42,"transparent");
    vign.addColorStop(1,"rgba(0,0,0,.22)");ctx.fillStyle=vign;ctx.fillRect(0,0,W,H);

    const small=W<900;
    const cx=small?W*.53:W*.67,cy=small?H*.39:H*.47;
    const R=Math.min(W*(small?.34:.24),H*.34), thick=R*.115;
    const ay=t*Math.PI*2, ax=t*Math.PI*4;
    const sy=Math.sin(ay),cyy=Math.cos(ay),sx=Math.sin(ax),cxx=Math.cos(ax);

    const u={x:cyy,y:sx*sy,z:-cxx*sy};
    const v={x:0,y:cxx,z:sx};
    const n={x:sy,y:-sx*cyy,z:cxx*cyy};
    const project=(X,Y,Z)=>({x:cx+R*(u.x*X+v.x*Y+n.x*Z),y:cy+R*(u.y*X+v.y*Y+n.y*Z),z:u.z*X+v.z*Y+n.z*Z});

    ctx.save();ctx.translate(0,R*.68);
    const sh=ctx.createRadialGradient(cx,cy,0,cx,cy,R*1.25);
    sh.addColorStop(0,"rgba(0,0,0,.35)");sh.addColorStop(1,"transparent");
    ctx.scale(1,.2);ctx.fillStyle=sh;ctx.beginPath();ctx.arc(cx,cy,R*1.25,0,Math.PI*2);ctx.fill();ctx.restore();

    const seg=96, quads=[];
    for(let i=0;i<seg;i++){
      const a=i*Math.PI*2/seg,b=(i+1)*Math.PI*2/seg;
      const p1=project(Math.cos(a),Math.sin(a),-.115),p2=project(Math.cos(b),Math.sin(b),-.115);
      const p3=project(Math.cos(b),Math.sin(b),.115),p4=project(Math.cos(a),Math.sin(a),.115);
      quads.push({p:[p1,p2,p3,p4],z:(p1.z+p2.z+p3.z+p4.z)/4,i,a})
    }
    quads.sort((a,b)=>a.z-b.z);
    for(const q of quads){
      const rake=.5+.5*Math.cos(q.a-ay-.65);
      const ridge=q.i%2===0 ? .72:1.15;
      ctx.fillStyle=`rgb(${Math.round(118*rake*ridge+38)},${Math.round(67*rake*ridge+24)},${Math.round(29*rake*ridge+13)})`;
      ctx.beginPath();ctx.moveTo(q.p[0].x,q.p[0].y);
      for(let j=1;j<4;j++)ctx.lineTo(q.p[j].x,q.p[j].y);
      ctx.closePath();ctx.fill();
      ctx.strokeStyle=q.i%2?"rgba(20,8,2,.5)":"rgba(255,210,112,.22)";
      ctx.lineWidth=Math.max(1,W/1400);ctx.stroke()
    }

    const nearFront=n.z>=0;
    drawFace(nearFront?front:back,nearFront?1:-1,nearFront);

    function drawFace(tex,z,isFront){
      ctx.save();
      ctx.setTransform(u.x*R,u.y*R,v.x*R,v.y*R,cx+n.x*R*z*.115,cy+n.y*R*z*.115);
      ctx.beginPath();ctx.arc(0,0,1,0,Math.PI*2);ctx.clip();
      if(!isFront)ctx.scale(-1,1);
      ctx.drawImage(tex,-1,-1,2,2);

      const phase=t*Math.PI*2;
      const hx=.85*Math.sin(phase*1.35+.35);
      const hy=.55*Math.cos(phase*.8-.4);
      let gl=ctx.createLinearGradient(hx-1.1,hy-.15,hx+1.1,hy+.15);
      gl.addColorStop(0,"rgba(255,255,255,0)");
      gl.addColorStop(.38,"rgba(255,244,200,.05)");
      gl.addColorStop(.5,"rgba(255,250,222,.72)");
      gl.addColorStop(.61,"rgba(255,225,150,.1)");
      gl.addColorStop(1,"rgba(0,0,0,.18)");
      ctx.globalCompositeOperation="screen";ctx.fillStyle=gl;ctx.fillRect(-1.3,-1.3,2.6,2.6);
      ctx.globalCompositeOperation="source-over";
      ctx.strokeStyle="rgba(255,222,145,.55)";ctx.lineWidth=.018;
      ctx.beginPath();ctx.arc(0,0,.985,0,Math.PI*2);ctx.stroke();
      ctx.restore()
    }

    const grain=(Math.sin(t*Math.PI*2)*.5+.5)*.008;
    ctx.fillStyle=`rgba(255,230,180,${grain})`;ctx.fillRect(0,0,W,H)
  }

  function loop(now){
    if(!running)return;
    render(((now-start)%9000)/9000);
    raf=requestAnimationFrame(loop)
  }
  window.demo={
    canvas:hero,
    setTime(t){render(clamp(Number(t)||0,0,1))},
    pause(){running=false;cancelAnimationFrame(raf)}
  };
  addEventListener("resize",()=>render(0));
  raf=requestAnimationFrame(loop);

  function renderEdition(canvas,palette,index){
    const d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();
    canvas.width=Math.max(300,Math.round(r.width*d));
    canvas.height=canvas.width;
    const x=canvas.getContext("2d"),S=canvas.width,q=S/2,R=S*.35;
    let bg=x.createLinearGradient(0,0,S,S);
    bg.addColorStop(0,index===3?"#17191b":"#e8dfcf");
    bg.addColorStop(1,index===3?"#3a3337":"#c9bda8");
    x.fillStyle=bg;x.fillRect(0,0,S,S);
    x.fillStyle="rgba(20,15,10,.18)";x.beginPath();x.ellipse(q+R*.12,q+R*.76,R*.95,R*.17,0,0,Math.PI*2);x.fill();

    x.save();x.translate(q,q);x.rotate(-.16+index*.075);x.scale(1,.94);
    for(let i=0;i<64;i++){
      const a=i*Math.PI*2/64,b=(i+1)*Math.PI*2/64;
      x.fillStyle=i%2?palette.edge:palette.dark;
      x.beginPath();x.moveTo(Math.cos(a)*R,Math.sin(a)*R+R*.12);
      x.lineTo(Math.cos(b)*R,Math.sin(b)*R+R*.12);
      x.lineTo(Math.cos(b)*R,Math.sin(b)*R);x.lineTo(Math.cos(a)*R,Math.sin(a)*R);x.fill()
    }
    const fg=x.createRadialGradient(-R*.34,-R*.4,5,0,0,R);
    fg.addColorStop(0,palette.light);fg.addColorStop(.43,palette.mid);fg.addColorStop(1,palette.dark);
